37	// requireWellFormedSnapshot checks the exported bytes describe one complete
38	// contiguous chain. It reports rather than fails fatally so it is safe to
39	// call from helper goroutines.
40	func requireWellFormedSnapshot(t *testing.T, raw string) {
41		t.Helper()
42		var doc genericSnapshot
43		if err := json.Unmarshal([]byte(raw), &doc); err != nil {
44			t.Errorf("exported snapshot does not parse: %v", err)
45			return
46		}
47		if doc.Version != 1 {
48			t.Errorf("exported version=%d, want 1", doc.Version)
49		}
50		for i, block := range doc.Blocks {
51			if want := int64(i + 1); block.Height != want {
52				t.Errorf("exported block %d has height %d, want %d", i, block.Height, want)
53				return
54			}
55			if i > 0 && block.Parent != doc.Blocks[i-1].Hash {
56				t.Errorf("exported block at height %d breaks the parent link", block.Height)
57				return
58			}
59		}
60		last := int64(0)
61		if len(doc.Blocks) > 0 {
62			last = doc.Blocks[len(doc.Blocks)-1].Height
63		}
64		if doc.Tip != last {
65			t.Errorf("exported tip=%d, last height=%d", doc.Tip, last)
66		}
67	}
