443		if err := index.Restore(strings.NewReader(bad)); !errors.Is(err, ErrInvalidSnapshot) {
444			t.Fatalf("err=%v, want ErrInvalidSnapshot", err)
445		}
446		// The cursor issued before the failed restore still pages to the end.
447		pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: cursor})
448		var all []TxHit
449		for _, page := range pages {
450			all = append(all, page.Hits...)
451		}
452		want := []TxHit{
453			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
454			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
455		}
456		if !reflect.DeepEqual(all, want) {
457			t.Fatalf("hits=%v, want %v", all, want)
458		}
459	}
460	
461	func TestRestoreSameContentKeepsCursorDifferentContentKills(t *testing.T) {
462		build := func(t *testing.T) (*Index, string) {
463			t.Helper()
464			index := txChain(t,
465				[]string{"a"},
466				[]string{"b"},
467				[]string{"c"},
468			)
469			first, err := index.QueryTxs(TxQuery{PageSize: 1})
470			if err != nil {
471				t.Fatal(err)
472			}
473			return index, first.NextCursor
474		}
475	
476		t.Run("identical restore keeps the cursor", func(t *testing.T) {
477			index, cursor := build(t)
478			raw := exportString(t, index)
479			if err := index.Restore(strings.NewReader(raw)); err != nil {
480				t.Fatal(err)
481			}
482			page, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor})
483			if err != nil {
484				t.Fatalf("continuation after identical restore failed: %v", err)
485			}
486			want := []TxHit{{Height: 2, BlockHash: "h2", TxID: "b", Position: 0}}
487			if !reflect.DeepEqual(page.Hits, want) {
488				t.Fatalf("hits=%v, want %v", page.Hits, want)
489			}
490		})
491	
492		t.Run("changed range kills the cursor", func(t *testing.T) {
493			index, cursor := build(t)
494			snap := `{"version":1,"tip":3,"blocks":[` +
495				`{"height":1,"hash":"h1","parent":"genesis","txs":["a"]},` +
496				`{"height":2,"hash":"h2","parent":"h1","txs":["CHANGED"]},` +
497				`{"height":3,"hash":"h3","parent":"h2","txs":["c"]}` +
498				`]}`
499			if err := index.Restore(strings.NewReader(snap)); err != nil {
500				t.Fatal(err)
501			}
502			if _, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
503				t.Fatalf("err=%v, want ErrQueryChanged", err)
504			}
505		})
506	
507		t.Run("shortened chain kills the cursor", func(t *testing.T) {
508			index, cursor := build(t)
509			snap := `{"version":1,"tip":1,"blocks":[` +
510				`{"height":1,"hash":"h1","parent":"genesis","txs":["a"]}` +
511				`]}`
512			if err := index.Restore(strings.NewReader(snap)); err != nil {
513				t.Fatal(err)
514			}
515			if _, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
516				t.Fatalf("err=%v, want ErrQueryChanged", err)
517			}
518		})
519	}
520	
521	func TestRestoreWhileStreamOpenIndexStaysUsable(t *testing.T) {
522		index := txChain(t, []string{"a"}, []string{"b"})
523		pr, pw := io.Pipe()
524		done := make(chan error, 1)
525		go func() {
526			done <- index.Restore(pr)
527		}()
528		// Deliver only a prefix; the restore is now blocked mid-stream.
529		if _, err := pw.Write([]byte(`{"version":1,"tip":0,`)); err != nil {
530			t.Fatal(err)
531		}
532		// The index stays queryable and appendable while the stream is open.
533		page, err := index.QueryTxs(TxQuery{})
534		if err != nil || page.TotalMatches != 2 {
535			t.Fatalf("query while restore in flight: page=%+v err=%v", page, err)
536		}
537		if err := index.Append(Block{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"c"}}); err != nil {
538			t.Fatalf("append while restore in flight: %v", err)
539		}
540		// Ending the stream early fails the restore without touching the chain.
541		if err := pw.Close(); err != nil {
542			t.Fatal(err)
543		}
544		if err := <-done; !errors.Is(err, ErrInvalidSnapshot) {
545			t.Fatalf("restore err=%v, want ErrInvalidSnapshot", err)
546		}
547		// Only the append changed the chain; the failed restore left no trace.
548		if index.Tip != 3 || len(index.Blocks) != 3 || index.Blocks[3].Hash != "h3" {
549			t.Fatalf("unexpected state: tip=%d blocks=%v", index.Tip, index.Blocks)
550		}
551	}
552	
553	func TestSnapshotConcurrentWithChainOps(t *testing.T) {
554		source := txChain(t, []string{"seed"})
555		var wg sync.WaitGroup
556	
557		// One writer keeps appending; exporters must always observe one complete
558		// contiguous chain.
559		stop := make(chan struct{})
560		var writer sync.WaitGroup
561		writer.Add(1)
562		go func() {
563			defer writer.Done()
564			for height := int64(2); height <= 300; height++ {
565				select {
566				case <-stop:
567					return
568				default:
569				}
570				block := Block{
571					Height: height,
572					Hash:   fmt.Sprintf("h%d", height),
573					Parent: fmt.Sprintf("h%d", height-1),
574					Txs:    []string{fmt.Sprintf("tx-%d", height)},
575				}
576				if err := source.Append(block); err != nil {
577					return
578				}
579			}
580		}()
581	
582		for exporter := 0; exporter < 3; exporter++ {
583			wg.Add(1)
584			go func() {
585				defer wg.Done()
586				for round := 0; round < 30; round++ {
587					var buf bytes.Buffer
588					if err := source.Export(&buf); err != nil {
589						t.Errorf("export failed: %v", err)
590						return
591					}
592					requireWellFormedSnapshot(t, buf.String())
593				}
594			}()
595		}
596	
597		// Restores and queries race on a second index; every restore applies a
598		// complete snapshot, so queries always see a contiguous chain.
599		target := New()
600		raw := exportString(t, txChain(t,
601			[]string{"a", "b"},
602			[]string{"c"},
603			[]string{"d"},
604		))
605		for worker := 0; worker < 2; worker++ {
606			wg.Add(1)
607			go func() {
608				defer wg.Done()
609				for round := 0; round < 20; round++ {
610					if err := target.Restore(strings.NewReader(raw)); err != nil {
611						t.Errorf("restore failed: %v", err)
612						return
613					}
614				}
615			}()
616		}
617		for reader := 0; reader < 2; reader++ {
618			wg.Add(1)
619			go func() {
620				defer wg.Done()
621				for round := 0; round < 40; round++ {
622					page, err := target.QueryTxs(TxQuery{})
623					if err != nil {
624						t.Errorf("query failed: %v", err)
625						return
626					}
627					lastHeight, lastPosition := int64(0), -1
628					for _, hit := range page.Hits {
629						if hit.Height < lastHeight || (hit.Height == lastHeight && hit.Position <= lastPosition) {
630							t.Errorf("hits out of order: %+v after (%d,%d)", hit, lastHeight, lastPosition)
631							return
632						}
633						lastHeight, lastPosition = hit.Height, hit.Position
634					}
635				}
636			}()
637		}
638	
639		wg.Wait()
640		close(stop)
641		writer.Wait()
642	}
