1	package indexroom
2	
3	import (
4		"fmt"
5	)
6	
7	// MaxTimeBuckets is the largest number of segments one QueryTimeStats call
8	// may return.
9	const MaxTimeBuckets = 10000
10	
11	// TimeStatsQuery asks for transaction statistics over a half-open time
12	// window, segmented into fixed-length buckets.
13	//
14	// From and To reuse the TxQuery height semantics: heights are inclusive, a
15	// zero From starts at height 1, a zero To pins the chain tip, and an
16	// explicit To above the tip is clamped to it. TxIDs reuses the exact-string
17	// filter semantics, including duplicates and empty identifiers.
18	//
19	// Start and End are Unix seconds bounding the window [Start, End): Start is
20	// included, End is excluded. Both must be non-negative and Start must be
21	// below End. StepSeconds is the bucket length in seconds and must be
22	// positive; buckets start at Start and the final bucket is cut off at End.
23	// Times outside any int64 range cannot be requested.
24	type TimeStatsQuery struct {
25		From        int64
26		To          int64
27		TxIDs       []string
28		Start       int64
29		End         int64
30		StepSeconds int64
31	}
32	
33	// TimeBucket is statistics for one half-open segment [Start, End). Buckets
34	// with no matching transactions are returned with every count at zero.
35	type TimeBucket struct {
36		Start int64
37		End   int64
38		// TxCount counts matching transaction occurrences in the segment.
39		TxCount int64
40		// DistinctTxIDs counts the different matching identifiers in the segment.
41		DistinctTxIDs int64
42		// Blocks counts blocks whose timestamp falls in the segment and which
43		// hold at least one matching transaction.
44		Blocks int64
45	}
46	
47	// TimeTotals summarizes the whole window with the same counters as a bucket.
48	// DistinctTxIDs is deduplicated over the whole window, not summed from the
49	// per-bucket values.
50	type TimeTotals struct {
51		TxCount       int64
52		DistinctTxIDs int64
53		Blocks        int64
54	}
55	
56	// TimeStats is the result of QueryTimeStats. Buckets are ordered by ascending
57	// time and always cover the whole requested window, even on an empty chain,
58	// above the chain tip, or when nothing matches. MissingTimeBlocks reports how
59	// many blocks in the resolved height range carry no timestamp; those blocks
60	// never enter a bucket, and the count ignores the transaction filter.
61	type TimeStats struct {
62		Buckets []TimeBucket
63		Totals  TimeTotals
64		// FromHeight and ToHeight are the resolved inclusive height bounds,
65		// clamped to the chain tip observed by this call.
66		FromHeight int64
67		ToHeight   int64
68		// MissingTimeBlocks counts blocks in [FromHeight, ToHeight] without a
69		// timestamp, regardless of the transaction filter.
70		MissingTimeBlocks int64
71	}
72	
73	// QueryTimeStats buckets matching transactions by block timestamp over the
74	// requested height range. The call observes one complete main-chain state:
75	// concurrent Append, Reorg, or Restore calls never mix old and new blocks
76	// into the answer, and the index is never modified.
77	func (index *Index) QueryTimeStats(query TimeStatsQuery) (TimeStats, error) {
78		from, to, err := normalizeRange(query.From, query.To)
79		if err != nil {
80			return TimeStats{}, err
81		}
82		if query.Start < 0 {
83			return TimeStats{}, fmt.Errorf("%w: start time must not be negative", ErrInvalidArgument)
84		}
85		if query.End < 0 {
86			return TimeStats{}, fmt.Errorf("%w: end time must not be negative", ErrInvalidArgument)
87		}
88		if query.Start >= query.End {
89			return TimeStats{}, fmt.Errorf("%w: start time must be below end time", ErrInvalidArgument)
90		}
91		if query.StepSeconds <= 0 {
92			return TimeStats{}, fmt.Errorf("%w: step seconds must be positive", ErrInvalidArgument)
93		}
94	
95		// Window length is positive and bounded by MaxInt64 since End > Start.
96		width := query.End - query.Start
97		count := width / query.StepSeconds
98		if width%query.StepSeconds != 0 {
99			count++
100		}
101		if count > MaxTimeBuckets {
102			return TimeStats{}, fmt.Errorf("%w: time window would produce %d buckets, limit is %d",
103				ErrInvalidArgument, count, MaxTimeBuckets)
104		}
105	
106		var filter map[string]struct{}
107		if len(query.TxIDs) > 0 {
108			filter = make(map[string]struct{}, len(query.TxIDs))
109			for _, id := range query.TxIDs {
110				filter[id] = struct{}{}
111			}
112		}
113	
114		stats := TimeStats{Buckets: make([]TimeBucket, count)}
115		for i := range stats.Buckets {
116			stats.Buckets[i].Start = bucketBoundary(query.Start, query.StepSeconds, int64(i))
117			// A saturated boundary (MaxInt64) and the overshooting final step
118			// are both cut back to the requested window end.
119			end := bucketBoundary(query.Start, query.StepSeconds, int64(i)+1)
120			if end > query.End {
121				end = query.End
122			}
123			stats.Buckets[i].End = end
124		}
125	
126		index.mu.Lock()
127		defer index.mu.Unlock()
128	
129		if to == 0 || to > index.Tip {
130			to = index.Tip
131		}
132		stats.FromHeight = from
133		stats.ToHeight = to
134		if from > to {
135			// Empty index or a start above the tip: zeroed buckets are still
136			// returned for the whole requested window.
137			return stats, nil
138		}
139	
140		distinct := make([]map[string]struct{}, count)
141		windowDistinct := make(map[string]struct{})
142		for height := from; height <= to; height++ {
143			block := index.Blocks[height]
144			if block.Time == nil {
145				stats.MissingTimeBlocks++
146				continue
147			}
148			t := *block.Time
149			if t < query.Start || t >= query.End {
150				continue
151			}
152			bucket := (t - query.Start) / query.StepSeconds
153			matched := false
154			for _, tx := range block.Txs {
155				if filter != nil {
156					if _, ok := filter[tx]; !ok {
157						continue
158					}
159				}
160				stats.Buckets[bucket].TxCount++
161				stats.Totals.TxCount++
162				if distinct[bucket] == nil {
163					distinct[bucket] = make(map[string]struct{})
164				}
165				distinct[bucket][tx] = struct{}{}
166				windowDistinct[tx] = struct{}{}
167				matched = true
168			}
169			if matched {
170				stats.Buckets[bucket].Blocks++
171				stats.Totals.Blocks++
172			}
173		}
174		for i := range distinct {
175			stats.Buckets[i].DistinctTxIDs = int64(len(distinct[i]))
176		}
177		stats.Totals.DistinctTxIDs = int64(len(windowDistinct))
178		return stats, nil
179	}
180	
181	// bucketBoundary returns Start + step*index, saturated at MaxInt64 instead
182	// of overflowing. Callers cut saturated and trailing boundaries back to the
183	// requested window end.
