514		pageA, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor})
515		if err != nil {
516			t.Fatal(err)
517		}
518		pageB, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor})
519		if err != nil {
520			t.Fatal(err)
521		}
522		if !reflect.DeepEqual(pageA, pageB) {
523			t.Fatalf("repeated cursor returned different pages:\n%+v\n%+v", pageA, pageB)
524		}
525	}
526	
527	func TestQueryTxsReturnedHitsAreCopies(t *testing.T) {
528		index := txChain(t, []string{"a", "b"})
529		page, err := index.QueryTxs(TxQuery{})
530		if err != nil {
531			t.Fatal(err)
532		}
533		page.Hits[0].TxID = "mutated"
534		page.Hits[0].BlockHash = "mutated"
535		page.Hits[0].Height = 99
536		again, err := index.QueryTxs(TxQuery{})
537		if err != nil {
538			t.Fatal(err)
539		}
540		want := TxHit{Height: 1, BlockHash: "h1", TxID: "a", Position: 0}
541		if again.Hits[0] != want {
542			t.Fatalf("caller mutation leaked into the index: %+v", again.Hits[0])
543		}
544	}
545	
546	func TestQueryTxsDoesNotMutateIndex(t *testing.T) {
547		index := txChain(t,
548			[]string{"a", "b"},
549			[]string{"c"},
550		)
551		blocks, byHash, tip := snapshot(index)
552		for _, page := range collectPages(t, index, TxQuery{PageSize: 1}) {
553			_ = page
554		}
555		requireUnchanged(t, index, blocks, byHash, tip)
556	}
557	
558	func TestQueryTxsConcurrentWithAppends(t *testing.T) {
559		index := chain(t, Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"tx-1"}})
560		stop := make(chan struct{})
561	
562		var writer sync.WaitGroup
563		writer.Add(1)
564		go func() {
565			defer writer.Done()
566			for height := int64(2); height <= 200; height++ {
567				select {
568				case <-stop:
569					return
570				default:
571				}
572				block := Block{
573					Height: height,
574					Hash:   fmt.Sprintf("h%d", height),
575					Parent: fmt.Sprintf("h%d", height-1),
576					Txs:    []string{fmt.Sprintf("tx-%d", height)},
577				}
578				if err := index.Append(block); err != nil {
579					return
580				}
581			}
582		}()
583	
584		var readers sync.WaitGroup
585		for reader := 0; reader < 4; reader++ {
586			readers.Add(1)
587			go func() {
588				defer readers.Done()
589				for round := 0; round < 20; round++ {
590					// Appends above the pinned range never invalidate a query,
591					// so every pagination run must complete and stay consistent.
592					pages := 0
593					seen := 0
594					var total, matched, to int64 = -1, -1, -1
595					query := TxQuery{PageSize: 7}
596					var lastHeight int64
597					var lastPosition = -1
598					for {
599						page, err := index.QueryTxs(query)
600						if err != nil {
601							t.Errorf("query failed during appends: %v", err)
602							return
603						}
604						if total == -1 {
605							total, matched, to = page.TotalMatches, page.MatchedBlocks, page.ToHeight
606						} else if page.TotalMatches != total || page.MatchedBlocks != matched || page.ToHeight != to {
607							t.Errorf("stats changed mid-pagination: %+v", page)
608							return
609						}
610						for _, hit := range page.Hits {
611							if hit.Height < lastHeight || (hit.Height == lastHeight && hit.Position <= lastPosition) {
612								t.Errorf("hits out of order after (%d,%d): %+v", lastHeight, lastPosition, hit)
613								return
614							}
615							if hit.Height > page.ToHeight {
616								t.Errorf("hit above pinned bound: %+v vs %d", hit, page.ToHeight)
617								return
618							}
619							lastHeight, lastPosition = hit.Height, hit.Position
620						}
621						seen += len(page.Hits)
622						pages++
623						if page.NextCursor == "" {
624							break
625						}
626						query.Cursor = page.NextCursor
627					}
628					if int64(seen) != total {
629						t.Errorf("paginated %d hits over %d pages, total says %d", seen, pages, total)
630						return
631					}
632				}
633			}()
634		}
635		readers.Wait()
636		close(stop)
637		writer.Wait()
638	}
