405				for height := int64(2); height <= 200; height++ {
406					select {
407					case <-stop:
408						return
409					default:
410					}
411					b := timeBlock(height, fmt.Sprintf("h%d", height),
412						fmt.Sprintf("h%d", height-1), []string{fmt.Sprintf("tx-%d", height)}, intptr(height))
413					if err := index.Append(b); err != nil {
414						return
415					}
416				}
417			}()
418		}
419		var readers sync.WaitGroup
420		for r := 0; r < 4; r++ {
421			readers.Add(1)
422			go func() {
423				defer readers.Done()
424				for i := 0; i < 100; i++ {
425					stats, err := index.QueryTimeStats(TimeStatsQuery{Start: 0, End: 201, StepSeconds: 7})
426					if err != nil {
427						t.Errorf("stats failed: %v", err)
428						return
429					}
430					// Internal consistency against one snapshot: per-bucket
431					// occurrence counts sum to the window total.
432					var sum int64
433					for _, b := range stats.Buckets {
434						sum += b.TxCount
435						if b.Start < 0 || b.End <= b.Start {
436							t.Errorf("bad bucket %+v", b)
437							return
438						}
439					}
440					if sum != stats.Totals.TxCount {
441						t.Errorf("bucket counts %d != total %d", sum, stats.Totals.TxCount)
442						return
443					}
444				}
445			}()
446		}
447		readers.Wait()
448		close(stop)
449		writers.Wait()
450	}
