18	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
19	
20	const (
21		// snapshotVersion1 is the timestamp-less layout. It stays readable
22		// indefinitely; its blocks restore with missing timestamps.
23		snapshotVersion1 = 1
24		// snapshotVersion2 adds a required timestamp field to every block:
25		// either a non-negative Unix-seconds integer or null for missing time.
26		snapshotVersion2 = 2
27	)
