32	// snapshotDoc is the version-1 wire form of an exported main chain.
33	type snapshotDoc struct {
34		Version int64           `json:"version"`
35		Tip     int64           `json:"tip"`
36		Blocks  []snapshotBlock `json:"blocks"`
37	}
38	
39	// snapshotBlock is the version-1 wire form of one block.
40	type snapshotBlock struct {
41		Height int64    `json:"height"`
42		Hash   string   `json:"hash"`
43		Parent string   `json:"parent"`
44		Txs    []string `json:"txs"`
45	}
46	
47	// snapshotDocV2 is the timestamp-bearing wire form.
48	type snapshotDocV2 struct {
49		Version int64             `json:"version"`
50		Tip     int64             `json:"tip"`
51		Blocks  []snapshotBlockV2 `json:"blocks"`
52	}
53	
54	// snapshotBlockV2 is the version-2 wire form of one block. A nil Timestamp
55	// serializes as null.
56	type snapshotBlockV2 struct {
57		Height    int64    `json:"height"`
58		Hash      string   `json:"hash"`
59		Parent    string   `json:"parent"`
60		Txs       []string `json:"txs"`
61		Timestamp *int64   `json:"timestamp"`
62	}
63	
64	// Export writes the current main chain to w as a JSON snapshot: a single
65	// object with version, tip, and the blocks ordered by ascending height, each
66	// carrying its transactions in order. The same main chain always produces
67	// the same bytes, regardless of the reorg, restore, or query history that
68	// led to it. Only blocks in effect at export time appear; nothing the index
69	// once held and later dropped is included.
