76	// Export observes one complete chain state and never modifies the index.
77	// The chain is copied under the lock and serialized afterwards, so queries
78	// and appends proceed while the stream is still being written. A write
79	// failure is reported and leaves the index untouched.
80	func (index *Index) Export(w io.Writer) error {
81		index.mu.Lock()
