86				break
87			}
88		}
89		var raw []byte
90		var err error
91		if version == snapshotVersion1 {
92			doc := snapshotDoc{
93				Version: snapshotVersion1,
94				Tip:     index.Tip,
95				Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
96			}
97			for height := int64(1); height <= index.Tip; height++ {
98				block := index.Blocks[height]
99				txs := make([]string, len(block.Txs))
100				copy(txs, block.Txs)
101				doc.Blocks = append(doc.Blocks, snapshotBlock{
102					Height: block.Height,
103					Hash:   block.Hash,
104					Parent: block.Parent,
105					Txs:    txs,
106				})
107			}
108			index.mu.Unlock()
109			raw, err = json.Marshal(doc)
110		} else {
111			doc := snapshotDocV2{
112				Version: snapshotVersion2,
113				Tip:     index.Tip,
114				Blocks:  make([]snapshotBlockV2, 0, int(index.Tip)),
115			}
116			for height := int64(1); height <= index.Tip; height++ {
117				block := index.Blocks[height]
118				txs := make([]string, len(block.Txs))
119				copy(txs, block.Txs)
120				entry := snapshotBlockV2{
121					Height: block.Height,
122					Hash:   block.Hash,
123					Parent: block.Parent,
124					Txs:    txs,
125				}
126				if block.Time != nil {
127					t := *block.Time
128					entry.Timestamp = &t
129				}
130				doc.Blocks = append(doc.Blocks, entry)
131			}
132			index.mu.Unlock()
133			raw, err = json.Marshal(doc)
134		}
135		if err != nil {
136			panic(err) // snapshot docs only contain marshalable fields
137		}
138		n, err := w.Write(raw)
139		if err != nil {
140			return fmt.Errorf("indexroom: export snapshot: %w", err)
141		}
142		if n != len(raw) {
143			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
144		}
145		return nil
146	}
147	
148	// Restore replaces the whole main chain with the snapshot read from r. The
149	// input must be exactly one snapshot object, optionally followed by
150	// whitespace; every block is validated — including heights ascending from 1,
151	// non-empty unique hashes, and parent linkage — before anything is applied.
152	// The first block's parent is exempt from linkage: it names the chain start
153	// and need not be indexed.
154	//
155	// The replacement takes effect as one complete operation: on success the
156	// index holds exactly the snapshot chain with no leftover heights or hashes,
157	// and on any failure — a read error or an invalid block discovered at the
158	// very end — the current chain and every previously issued cursor remain as
159	// they were. The stream is consumed and validated before the lock is taken,
160	// so the index stays queryable and appendable while the restore is reading.
161	//
162	// After a successful restore, cursors issued earlier by this same index keep
163	// working wherever the pinned range still matches and the tip still covers
164	// it; otherwise continuations fail with ErrQueryChanged as usual.
165	func (index *Index) Restore(r io.Reader) error {
166		tip, blocks, err := parseSnapshot(r)
167		if err != nil {
168			return err
169		}
170		stored := make(map[int64]Block, len(blocks))
171		byHash := make(map[string]int64, len(blocks))
172		for _, block := range blocks {
173			stored[block.Height] = block
174			byHash[block.Hash] = block.Height
175		}
176		index.mu.Lock()
177		index.Blocks = stored
178		index.ByHash = byHash
179		index.Tip = tip
180		index.mu.Unlock()
181		return nil
182	}
183	
184	// parseSnapshot reads and fully validates one snapshot document. It returns
185	// the tip height and the validated blocks in ascending height order.
186	func parseSnapshot(r io.Reader) (int64, []Block, error) {
187		dec := json.NewDecoder(r)
188		tok, err := dec.Token()
189		if err != nil {
190			return 0, nil, classifySnapshotErr(err)
191		}
192		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
193			return 0, nil, invalidSnapshot("snapshot must be a single JSON object")
194		}
195	
196		// Top-level fields are captured raw so blocks can be parsed with the
197		// strict schema matching the declared version, whatever the field order.
198		var (
199			version, tip         int64
200			rawBlocks            json.RawMessage
201			haveVersion, haveTip bool
202			haveBlocks           bool
203			seen                 = map[string]bool{}
204		)
205		for dec.More() {
206			key, err := snapshotKey(dec)
207			if err != nil {
208				return 0, nil, err
209			}
210			if seen[key] {
211				return 0, nil, invalidSnapshot("duplicate field %q", key)
212			}
213			seen[key] = true
214			switch key {
215			case "version":
216				v, err := decodeSnapshotIntField(dec, key)
217				if err != nil {
218					return 0, nil, err
219				}
220				version = v
221				haveVersion = true
222			case "tip":
223				v, err := decodeSnapshotIntField(dec, key)
224				if err != nil {
225					return 0, nil, err
226				}
227				tip = v
228				haveTip = true
229			case "blocks":
230				if err := dec.Decode(&rawBlocks); err != nil {
231					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
232				}
233				haveBlocks = true
234			default:
235				return 0, nil, invalidSnapshot("unknown field %q", key)
236			}
237		}
238		if _, err := dec.Token(); err != nil { // closing '}'
239			return 0, nil, classifySnapshotErr(err)
240		}
241		// Only whitespace may follow the snapshot object.
242		if _, err := dec.Token(); err != io.EOF {
243			if err == nil {
244				return 0, nil, invalidSnapshot("trailing data after the snapshot object")
245			}
246			return 0, nil, classifySnapshotErr(err)
247		}
248	
249		if !haveVersion {
250			return 0, nil, invalidSnapshot("missing field %q", "version")
251		}
252		if !haveTip {
253			return 0, nil, invalidSnapshot("missing field %q", "tip")
254		}
255		if !haveBlocks {
256			return 0, nil, invalidSnapshot("missing field %q", "blocks")
257		}
258		if version != snapshotVersion1 && version != snapshotVersion2 {
259			return 0, nil, invalidSnapshot("unsupported version %d", version)
260		}
261	
262		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
263		blocks, err := parseSnapshotBlocks(blockDec, version)
264		if err != nil {
265			return 0, nil, err
266		}
267		if _, err := blockDec.Token(); err != io.EOF {
268			if err == nil {
269				return 0, nil, invalidSnapshot("trailing data after the blocks array")
270			}
271			return 0, nil, classifySnapshotErr(err)
272		}
273	
274		lastHeight := int64(0)
275		if len(blocks) > 0 {
276			lastHeight = blocks[len(blocks)-1].Height
277		}
278		if tip != lastHeight {
279			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
280		}
281		return tip, blocks, nil
282	}
283	
284	// parseSnapshotBlocks reads the blocks array value, validating heights,
285	// hashes, parent links, and (for version 2) timestamps as it goes.
286	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
287		tok, err := dec.Token()
288		if err != nil {
289			return nil, classifySnapshotErr(err)
290		}
291		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
292			return nil, invalidSnapshot("field %q must be an array", "blocks")
293		}
294		blocks := []Block{}
295		seenHash := map[string]bool{}
296		for dec.More() {
297			var block Block
298			if version == snapshotVersion2 {
299				block, err = parseSnapshotBlockV2(dec)
300			} else {
301				block, err = parseSnapshotBlock(dec)
302			}
303			if err != nil {
304				return nil, err
305			}
306			want := int64(len(blocks) + 1)
307			if block.Height != want {
308				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
309			}
310			if block.Hash == "" {
311				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
312			}
313			if seenHash[block.Hash] {
314				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
315			}
316			seenHash[block.Hash] = true
317			// The first block's parent names the chain start and is exempt from
318			// linkage; every later block must point at its predecessor.
319			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
320				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
321			}
322			blocks = append(blocks, block)
323		}
324		if _, err := dec.Token(); err != nil { // closing ']'
325			return nil, classifySnapshotErr(err)
326		}
327		return blocks, nil
328	}
329	
330	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
331	// fields height, hash, parent, and txs.
332	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
333		var block Block
334		tok, err := dec.Token()
335		if err != nil {
336			return block, classifySnapshotErr(err)
337		}
338		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
339			return block, invalidSnapshot("block must be a JSON object")
340		}
341		var haveHeight, haveHash, haveParent, haveTxs bool
342		var txNulls []int
343		seen := map[string]bool{}
344		for dec.More() {
345			key, err := snapshotKey(dec)
346			if err != nil {
347				return block, err
348			}
349			if seen[key] {
350				return block, invalidSnapshot("duplicate block field %q", key)
351			}
352			seen[key] = true
353			switch key {
354			case "height":
355				v, err := decodeSnapshotIntField(dec, key)
356				if err != nil {
357					return block, err
358				}
359				block.Height = v
360				haveHeight = true
361			case "hash":
362				v, err := decodeSnapshotStringField(dec, key)
363				if err != nil {
364					return block, err
365				}
366				block.Hash = v
367				haveHash = true
368			case "parent":
369				v, err := decodeSnapshotStringField(dec, key)
370				if err != nil {
371					return block, err
372				}
373				block.Parent = v
374				haveParent = true
375			case "txs":
376				txs, nulls, err := parseSnapshotTxs(dec)
377				if err != nil {
378					return block, err
379				}
380				block.Txs = txs
381				txNulls = nulls
382				haveTxs = true
383			default:
384				return block, invalidSnapshot("unknown block field %q", key)
385			}
386		}
387		if _, err := dec.Token(); err != nil { // closing '}'
388			return block, classifySnapshotErr(err)
389		}
390		for field, present := range map[string]bool{
391			"height": haveHeight,
392			"hash":   haveHash,
393			"parent": haveParent,
394			"txs":    haveTxs,
395		} {
396			if !present {
397				return block, invalidSnapshot("block is missing field %q", field)
398			}
399		}
400		// Reject null tx elements now that the block height is known, so the
401		// error can pinpoint both the block and the 0-based position.
402		if len(txNulls) > 0 {
403			return block, invalidSnapshot("txs element at block height %d, position %d must not be null", block.Height, txNulls[0])
404		}
405		return block, nil
406	}
407	
408	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
409	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
410	// null or a non-negative integer; the block returns a nil time for null.
411	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
412		var block Block
413		tok, err := dec.Token()
414		if err != nil {
415			return block, classifySnapshotErr(err)
416		}
417		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
418			return block, invalidSnapshot("block must be a JSON object")
419		}
420		var haveHeight, haveHash, haveParent, haveTxs, haveTimestamp bool
421		var txNulls []int
422		seen := map[string]bool{}
423		for dec.More() {
424			key, err := snapshotKey(dec)
425			if err != nil {
426				return block, err
427			}
428			if seen[key] {
429				return block, invalidSnapshot("duplicate block field %q", key)
430			}
431			seen[key] = true
432			switch key {
433			case "height":
434				v, err := decodeSnapshotIntField(dec, key)
435				if err != nil {
436					return block, err
437				}
438				block.Height = v
439				haveHeight = true
440			case "hash":
441				v, err := decodeSnapshotStringField(dec, key)
442				if err != nil {
443					return block, err
444				}
445				block.Hash = v
446				haveHash = true
447			case "parent":
448				v, err := decodeSnapshotStringField(dec, key)
449				if err != nil {
450					return block, err
451				}
452				block.Parent = v
453				haveParent = true
454			case "txs":
455				txs, nulls, err := parseSnapshotTxs(dec)
456				if err != nil {
457					return block, err
458				}
459				block.Txs = txs
460				txNulls = nulls
461				haveTxs = true
462			case "timestamp":
463				t, err := parseSnapshotTimestamp(dec)
464				if err != nil {
465					return block, err
466				}
467				block.Time = t
468				haveTimestamp = true
469			default:
470				return block, invalidSnapshot("unknown block field %q", key)
471			}
472		}
473		if _, err := dec.Token(); err != nil { // closing '}'
474			return block, classifySnapshotErr(err)
475		}
476		for field, present := range map[string]bool{
477			"height":    haveHeight,
478			"hash":      haveHash,
479			"parent":    haveParent,
480			"txs":       haveTxs,
481			"timestamp": haveTimestamp,
482		} {
483			if !present {
484				return block, invalidSnapshot("block is missing field %q", field)
485			}
486		}
487		// Reject null tx elements now that the block height is known, so the
488		// error can pinpoint both the block and the 0-based position.
489		if len(txNulls) > 0 {
490			return block, invalidSnapshot("txs element at block height %d, position %d must not be null", block.Height, txNulls[0])
491		}
492		return block, nil
493	}
494	
495	// parseSnapshotTimestamp reads one timestamp value: null for a missing
496	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
497	// distinct from null.
498	func parseSnapshotTimestamp(dec *json.Decoder) (*int64, error) {
499		var t *int64
500		if err := dec.Decode(&t); err != nil {
501			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
502		}
503		if t != nil && *t < 0 {
504			return nil, invalidSnapshot("timestamp must not be negative")
505		}
506		return t, nil
507	}
508	
509	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
510	// identifiers exactly as written. Explicit null elements are recorded by
511	// 0-based position so callers can reject them once the block height is known.
512	func parseSnapshotTxs(dec *json.Decoder) (txs []string, nulls []int, err error) {
513		tok, err := dec.Token()
514		if err != nil {
515			return nil, nil, classifySnapshotErr(err)
516		}
517		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
518			return nil, nil, invalidSnapshot("field %q must be an array of strings", "txs")
519		}
520		txs = []string{}
521		for dec.More() {
522			var raw json.RawMessage
523			if err := dec.Decode(&raw); err != nil {
524				return nil, nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
525			}
526			if string(raw) == nullJSON {
527				nulls = append(nulls, len(txs))
528				txs = append(txs, "")
529				continue
530			}
531			var tx string
532			if err := json.Unmarshal(raw, &tx); err != nil {
533				return nil, nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
534			}
535			txs = append(txs, tx)
536		}
537		if _, err := dec.Token(); err != nil { // closing ']'
538			return nil, nil, classifySnapshotErr(err)
539		}
540		return txs, nulls, nil
541	}
542	
543	// snapshotKey reads the next object key.
544	func snapshotKey(dec *json.Decoder) (string, error) {
545		tok, err := dec.Token()
546		if err != nil {
547			return "", classifySnapshotErr(err)
548		}
549		key, ok := tok.(string)
550		if !ok {
551			return "", invalidSnapshot("object key must be a string")
552		}
553		return key, nil
554	}
555	
556	// decodeSnapshotIntField decodes an integer field, rejecting an explicit null
557	// that would otherwise silently become zero and look like a valid value.
558	func decodeSnapshotIntField(dec *json.Decoder, field string) (int64, error) {
559		var raw json.RawMessage
560		if err := dec.Decode(&raw); err != nil {
561			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
562		}
563		if string(raw) == nullJSON {
564			return 0, invalidSnapshot("field %q must not be null", field)
565		}
566		var v int64
567		if err := json.Unmarshal(raw, &v); err != nil {
568			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
569		}
570		return v, nil
571	}
572	
573	// decodeSnapshotStringField decodes a string field, rejecting an explicit null
574	// that would otherwise silently become the empty string.
575	func decodeSnapshotStringField(dec *json.Decoder, field string) (string, error) {
576		var raw json.RawMessage
577		if err := dec.Decode(&raw); err != nil {
578			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
579		}
580		if string(raw) == nullJSON {
581			return "", invalidSnapshot("field %q must not be null", field)
582		}
583		var v string
584		if err := json.Unmarshal(raw, &v); err != nil {
585			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
586		}
587		return v, nil
588	}
589	
590	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
591	func invalidSnapshot(format string, args ...any) error {
592		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
593	}
594	
595	// classifySnapshotErr maps decoder failures onto the snapshot error model:
596	// malformed JSON, wrong value types, and truncation are snapshot errors,
597	// while anything else is an underlying read failure reported as-is.
598	func classifySnapshotErr(err error) error {
599		var syntaxErr *json.SyntaxError
600		var typeErr *json.UnmarshalTypeError
601		switch {
602		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
603			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
604		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
605			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
606		default:
607			return fmt.Errorf("indexroom: read snapshot: %w", err)
608		}
609	}
610

